entries[178808] = { ["name"] = "Viscera of Coalesced Hatred", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+15 Strength\nEquip: Your abilities have a very high chance to lash out with a Hateful Strike, inflicting ( 237 * 1 ) Physical damage to an enemy and healing you for 7 . These effects are increased by 100% while you are below 35% health.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[178809] = { ["name"] = "Soulletting Ruby", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+15 Intellect\nUse: Draw out a piece of the target's soul, decreasing their movement speed by 30% until the soul reaches you. The soul instantly heals you for 597 , and grants you up to ( 70 + 86 ) Critical Strike for 16 sec. You gain more Critical Strike from lower health targets. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[178810] = { ["name"] = "Vial of Spectral Essence", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+15 Intellect\nUse: Bind a spectral essence to an enemy for 20 sec, causing allied attacks to heal for 30% of damage dealt, up to 2018 total healing.\n\nWhen the essence expires or is removed early, the remaining healing bursts, healing up to 5 allies within 8 yds. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
entries[178811] = { ["name"] = "Grim Codex", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+15 [Agility or Strength]\nUse: Conjure a Spectral Scythe, dealing 1550 Shadow damage to your target and 215 Shadow damage in a 15 yd cone to enemies behind your target. (1 Min, 30 Sec Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:" }
